/* Browser-local study app. All lessons and formula assets ship with the app. */
(() => {
 'use strict';
 const D=window.SIGNAL_DATA, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
 if(!D){$('#main').textContent='学习资料未加载，请刷新页面。';return;}
 const defaults={version:1,questions:{},training:{},font:false,dark:false};
 let state;try{state={...defaults,...JSON.parse(localStorage.getItem('sysu-signals-progress')||'{}')};}catch{state={...defaults};}
 const questions=D.exams.flatMap(e=>e.questions), drills=D.training;
 const all=[...questions,...drills], byId=new Map(all.map(q=>[q.id,q]));
 let current=null, currentQueue=[], currentIndex=0, expandedLimit=60, randomQueue=[];
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const clamp=n=>Math.max(0,Math.min(100,n));
 const icon=q=>state.questions[q.id]?.done?'已掌握 ✓':state.questions[q.id]?.wrong?'待复盘':'查看详解 →';
 function save(){try{localStorage.setItem('sysu-signals-progress',JSON.stringify(state));}catch{toast('浏览器未允许保存，请及时导出备份。');}}
 function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
 function md(text){
  let math=[];let input=String(text||'').replace(/\$\$[\s\S]*?\$\$|\$[^$\n]+\$|\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)/g,m=>`MATHPLACEHOLDER${math.push(m)-1}END`);
  let html=marked.parse(input,{breaks:false,gfm:true});
  html=html.replace(/MATHPLACEHOLDER(\d+)END/g,(_,i)=>escape(math[+i]));
  return html;
 }
 function typeset(el){renderMathInElement(el,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false},{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false}],throwOnError:false,strict:'ignore',trust:false});}
 function chapterName(id){return D.chapters.find(c=>c.chapter===id)?.name||id;}
 function tags(q){return (q.chapters||[]).slice(0,3).map(c=>`<span class="tag">${escape(c==='S'?'补充专题':`第${c}章`)} ${escape(chapterName(c).replace('周期信号的傅里叶级数表示','傅里叶级数').replace('信号与系统的时域和频域特性','幅相特性').replace('连续时间傅里叶变换','CTFT').replace('离散时间傅里叶变换','DTFT'))}</span>`).join('');}
 function heading(eyebrow,title,description){return `<p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${description}</p>`;}
 function options(values,selected,allLabel){return `<option value="">${allLabel}</option>`+values.map(([id,name])=>`<option value="${escape(id)}" ${String(id)===String(selected)?'selected':''}>${escape(name)}</option>`).join('');}
 function route(){let [page,query='']=location.hash.slice(1).split('?');return {page:page||'overview',params:new URLSearchParams(query)};}
 function navigate(page,params={}){location.hash=page+(Object.keys(params).length?'?'+new URLSearchParams(params):'');}
 function overview(){
  let done=questions.filter(q=>state.questions[q.id]?.done).length,wrong=questions.filter(q=>state.questions[q.id]?.wrong).length;
  let latest=[...all].filter(q=>state.questions[q.id]?.readAt).sort((a,b)=>state.questions[b.id].readAt-state.questions[a.id].readAt)[0];
  return `<section class="hero"><div><p class="eyebrow">面向中大 2027 · 逐题理解与迁移</p><h1>把每一道题，真正弄明白。</h1><p>从2008到2026，沿着频谱与系统两条主线复习。看清第一步，走完推导，再用同类题检查理解。</p><div class="inline-actions"><button class="primary" data-action="${latest?'open':'go'}" data-id="${latest?.id||''}" data-page="papers">${latest?'继续上次学习 →':'开始历年真题 →'}</button><button data-action="go" data-page="practice">进入专项训练</button></div></div><svg class="wave" viewBox="0 0 260 140" aria-label="信号波形示意"><path class="grid" d="M0 70h260M130 0v140M0 35h260M0 105h260M65 0v140M195 0v140"/><path class="signal" d="M0 70C12 70 16 62 24 62S38 85 45 85S61 45 70 45S89 107 99 107S119 13 130 13S150 126 161 126S182 38 191 38S207 89 216 89S234 61 241 61S254 70 260 70"/></svg></section>
  <div class="metrics"><div class="metric"><label>历年真题</label><strong>${D.exams.length}</strong><small>个年份</small></div><div class="metric"><label>独立题组详解</label><strong>${questions.length}</strong><small>组</small></div><div class="metric"><label>原创迁移训练</label><strong>${drills.length}</strong><small>道</small></div><div class="metric"><label>我的掌握进度</label><strong>${done}</strong><small>/ ${questions.length} 题组</small></div></div>
  <div class="section-head"><h2>优先练这三条主线</h2><a href="#chapters">查看完整考点分布 ↗</a></div><div class="paths"><a class="path-card" href="#papers?chapter=7"><span class="number">01 / 频谱处理</span><h3>求谱 · 调制 · 抽样 · 恢复</h3><p>第4、7、8章一起练。每一级先写公式，再标边界、幅度与相位。</p><div class="tags"><span class="tag">抽样涉及18年</span><span class="tag amber">近五年持续出现</span></div></a><a class="path-card" href="#papers?chapter=9"><span class="number">02 / 连续系统</span><h3>方程 · 电路 · 系统函数 · 响应</h3><p>第2、9、11章联练。先列节点关系，再处理极点、初态与稳定性。</p><div class="tags"><span class="tag">拉普拉斯涉及19年</span><span class="tag">初态与反向辨识</span></div></a><a class="path-card" href="#papers?chapter=10"><span class="number">03 / 离散系统</span><h3>差分 · Z变换 · ROC · 单位圆</h3><p>第5、10章联练。看清左右边序列、首个样值和隐藏模态。</p><div class="tags"><span class="tag">Z变换涉及18年</span><span class="tag">连续离散对照</span></div></a></div>
  <div class="two-col"><section><div class="section-head"><h2>按年份进入</h2><a href="#papers">全部真题 ↗</a></div><div class="year-links">${[...D.exams].reverse().map(e=>{let c=e.questions.filter(q=>state.questions[q.id]?.done).length;return `<a class="year-tile" href="#papers?year=${e.year}"><b>${e.year}</b><small>${e.questions.length}题组 · ${c}已掌握</small><div class="bar"><i style="width:${c/e.questions.length*100}%"></i></div></a>`;}).join('')}</div></section><section><div class="section-head"><h2>复习提示</h2><a href="#notebook">${wrong}道待复盘 ↗</a></div><div class="card"><h3>用覆盖年份判断侧重</h3><p class="muted" style="font-size:13px">基础客观题较碎，抽样综合题常连续追问多个环节。题组数量用于找题，不能直接当成分值比例。</p><div class="note">2025资料缺第4、5题；2021整理版编号由七跳至九。相关年份按可见题面记录，题面歧义在对应详解中说明。</div><p class="muted" style="font-size:12px">一般系统性质归第1章；用h判LTI因果稳定归第2章。正交投影与匹配滤波另列补充专题。</p></div></section></div><details><summary>阅读完整出题风格分析与复习优先级</summary><div class="lesson">${md(D.styleAnalysis||'')}</div></details>`;
 }
 function questionCard(q,training=false){let st=state.questions[q.id]||{};return `<button class="question-card" data-action="open" data-id="${escape(q.id)}"><span class="question-ref"><b>${training?q.ref:q.year}</b>${training?q.group:'第'+q.ref+'题'}</span><span class="question-main"><h3>${escape(q.title||q.summary)}</h3><p class="summary">${escape((q.statement||q.summary||'').replace(/\$|\\[a-zA-Z]+/g,'').slice(0,110))}</p><span class="tags">${tags(q)}${q.caveat?'<span class="tag amber">题面辨析</span>':''}${st.star?'<span class="tag amber">已收藏</span>':''}</span></span><span class="question-state">${icon(q)}</span></button>`;}
 function papers(p){let year=p.get('year')||'',chapter=p.get('chapter')||'',search=p.get('q')||'';let list=questions.filter(q=>(!year||String(q.year)===year)&&(!chapter||q.chapters.includes(chapter))&&(!search||(q.title+q.statement+q.summary+q.chapters.map(chapterName).join('')).toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.year-a.year||a.order-b.order);window.currentFiltered=list;
  let exam=D.exams.find(e=>String(e.year)===year);
  return heading('历年真题 / 2008—2026','从第一步开始，走完每一道题','按年份完整复盘，也可以按章节跨年对照。题干保留原题页供核对，讲解单独推导。')+`<div class="filters" data-filter="papers"><input id="paper-search" aria-label="搜索真题" placeholder="搜索：同初态、抽样、群时延…" value="${escape(search)}"><select id="paper-year" aria-label="选择年份">${options([...D.exams].reverse().map(e=>[e.year,e.year+'年']),year,'全部年份')}</select><select id="paper-chapter" aria-label="选择章节">${options(D.chapters.map(c=>[c.chapter,(c.chapter==='S'?'补充':c.chapter+'章')+' '+c.name]),chapter,'全部章节')}</select></div>${exam?.note?`<div class="note">${escape(exam.note)}</div>`:''}<div class="section-head"><h3>${list.length}个题组</h3><button class="plain" data-action="reset-filter">清除筛选</button></div><div class="question-list">${list.slice(0,expandedLimit).map(q=>questionCard(q)).join('')||'<div class="empty">没有匹配的题目，换个关键词试试。</div>'}</div>${list.length>expandedLimit?'<div style="text-align:center;margin-top:20px"><button data-action="load-more">继续加载题目</button></div>':''}`;
 }
 function practice(p){let chapter=p.get('chapter')||'',group=p.get('group')||'';let list=drills.filter(q=>(!chapter||q.chapters.includes(chapter))&&(!group||q.group===group));if(p.get('random')==='1'){if(!randomQueue.length)randomQueue=[...drills].sort(()=>Math.random()-.5).slice(0,5).map(q=>q.id);list=randomQueue.map(id=>byId.get(id));}window.currentFiltered=list;
  return heading('专项训练 / 原创迁移','把会做的真题，变成可迁移的方法','22道专项迁移练习和10道模拟综合题。先独立写，再展开推导；原书精选索引另附40道。')+`<div class="filters"><select id="practice-chapter" aria-label="训练章节">${options(D.chapters.map(c=>[c.chapter,(c.chapter==='S'?'补充':c.chapter+'章')+' '+c.name]),chapter,'全部章节')}</select><select id="practice-group" aria-label="训练类型">${options([['专项迁移','专项迁移'],['模拟综合','模拟综合']],group,'全部训练类型')}</select><button data-action="random-training">随机抽5题 ↗</button></div><div class="question-list">${list.map(q=>questionCard(q,true)).join('')||'<div class="empty">此分类暂没有单独训练题，可前往同章真题巩固。</div>'}</div><div class="section-head"><h2>奥本海姆第二版 · 40道精选</h2><a href="#downloads">下载配套习题集 ↗</a></div><div class="note">以下是原书题号、小问及训练起步。完整题干请对照手中第二版教材；上面的迁移题是独立编写的完整训练。</div><div class="table-scroll"><table><thead><tr><th>索引</th><th>原书题号与页码</th><th>次序</th><th>对应中大题与入手方法</th></tr></thead><tbody>${D.oppenheim.map(o=>`<tr><td>${escape(o.id)}</td><td>${escape(o.scope)}</td><td>${escape(o.priority)}</td><td style="white-space:normal;min-width:340px">${escape(o.reason)}</td></tr>`).join('')}</tbody></table></div>`;
 }
 function chapters(){
  return heading('考点地图 / 奥本海姆第二版','先看长期覆盖，再补自己的薄弱点','70类细分标签用于找题和复盘。综合题跨章记次，同章同题只记一次；数量不表示预测概率。')+`<div class="table-scroll"><table><thead><tr><th>章节</th><th>考点类别</th><th>涉及题组</th><th>覆盖年份</th><th>近五年</th><th>练习入口</th></tr></thead><tbody>${D.chapters.map(c=>`<tr><td>${c.chapter==='S'?'补充专题':`第${c.chapter}章 ${escape(c.name)}`}</td><td class="number">${c.types}</td><td class="number">${c.count}</td><td class="number">${c.year_count}/19</td><td class="number">${c.recent_years}/5</td><td><a style="color:var(--accent)" href="#papers?chapter=${c.chapter}">同章真题 →</a></td></tr>`).join('')}</tbody></table></div><div class="section-head"><h2>逐年考点分布</h2><span class="muted" style="font-size:12px">横向滑动查看全部章节</span></div><div class="table-scroll"><table class="heatmap"><thead><tr><th>年份</th>${D.chapters.map(c=>`<th>${c.chapter==='S'?'补充':c.chapter+'章'}</th>`).join('')}</tr></thead><tbody>${D.exams.map(e=>`<tr><td>${e.year}${[2021,2025].includes(e.year)?'*':''}</td>${D.chapters.map(c=>{let v=e.questions.filter(q=>q.chapters.includes(c.chapter)).length;return `<td class="cell" style="--v:${Math.min(8,v)}" title="${e.year}年${chapterName(c.chapter)}：${v}题组">${v}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:12px;margin-top:10px">* 2021编号跳号、2025缺题，0仅表示可见题面中未标记该章显式考点。</p><div class="section-head"><h2>各章具体练什么</h2><a href="#practice">进入专项训练 ↗</a></div><div class="chapter-grid">${D.chapters.map(c=>`<section class="chapter-card card"><p class="eyebrow">${c.chapter==='S'?'补充专题':'CHAPTER '+c.chapter} / ${c.priority}</p><h3>${escape(c.name)}</h3><div class="counts">${c.types}类考点 · ${c.count}个题组 · ${c.recent}个近五年题组</div><p class="muted" style="font-size:13px">${escape(c.focus)}</p><ul>${D.topics.filter(t=>t.chapter===c.chapter).map(t=>`<li>${escape(t.name)} <span class="muted">${t.count}题 / ${t.year_count}年</span></li>`).join('')}</ul><a class="button" href="#papers?chapter=${c.chapter}">查看对应真题 →</a></section>`).join('')}</div>`;
 }
 function notebook(p){let mode=p.get('mode')||'wrong',list=all.filter(q=>mode==='all'?state.questions[q.id]?.note:state.questions[q.id]?.[mode]);window.currentFiltered=list;return heading('我的复盘 / 本机记录','给没吃透的题，留一个位置','收藏、错题和笔记只保存在当前浏览器或当前安装包中。更换设备前可以导出备份。')+`<div class="filters"><button data-action="notebook-mode" data-mode="wrong" class="${mode==='wrong'?'primary':''}">待复盘</button><button data-action="notebook-mode" data-mode="star" class="${mode==='star'?'primary':''}">已收藏</button><button data-action="notebook-mode" data-mode="done" class="${mode==='done'?'primary':''}">已掌握</button><button data-action="notebook-mode" data-mode="all" class="${mode==='all'?'primary':''}">有笔记</button><button data-action="export">导出记录</button><button data-action="import">导入备份</button></div><div class="question-list">${list.map(q=>questionCard(q,!!q.training)).join('')||'<div class="empty">这里还没有题目。进入详解后，可标记“需复盘”或保存笔记。</div>'}</div>`;}
 function downloads(){let apk=D.files.find(f=>f.kind==='apk');let inAndroid=location.search.includes('android=1');return heading('资料与安装 / 离线可用','在网页学习，也能装进手机','Android版内置详解、配图与公式资源。学习记录保存在本机，网页支持导出、打印和备份。')+`<div class="download-grid">${D.files.map(f=>`<section class="download-card card"><span class="symbol">${f.kind==='apk'?'▣':f.kind==='xlsx'?'▦':'▤'}</span><h3>${escape(f.title)}</h3><p>${escape(f.description)}</p>${f.kind==='apk'&&inAndroid?'<span class="tag">当前已安装 1.0.1 离线版</span>':`<a class="button ${f.kind==='apk'?'primary':''}" href="${escape(f.path)}" download>${f.kind==='apk'?'下载 APK 安装包':'下载 '+f.kind.toUpperCase()} ↓</a>`}</section>`).join('')}<section class="download-card card"><span class="symbol">⌘</span><h3>独立仓库与源码</h3><p>${D.githubPublished?'源码、逐年讲解、原创专项训练、配图和构建方式，可继续维护和校订。':'全部源码已整理，等待创建独立 GitHub 仓库。现有仓库未写入内容。'}</p>${D.githubPublished?`<a class="button" href="${D.github}" target="_blank" rel="noopener">查看 GitHub →</a>`:'<span class="tag amber">新仓库待创建</span>'}</section><section class="download-card card"><span class="symbol">↔</span><h3>学习记录备份</h3><p>保存已掌握、错题、收藏和个人笔记。导入时合并记录，保留较新的修改。</p><div class="inline-actions"><button data-action="export">导出 JSON</button><button data-action="import">导入备份</button></div></section></div><div class="note">${apk?'安装时选择下载的 .apk 文件，按 Android 提示允许本次安装。':'安装包构建中。'} 这是个人备考工具，内容来自所供真题与独立推导，存在题面疑误的地方已在对应题中单独说明。</div><details><summary>记号与资料说明</summary><div class="lesson">${md(D.conventions)}</div></details>`;}
 const pageNames={overview:'学习总览',papers:'历年真题',practice:'专项训练',chapters:'考点地图',notebook:'错题与收藏',downloads:'资料与安装'};
 function render(){let {page,params}=route();if(!pageNames[page])page='overview';$('#breadcrumb').textContent=pageNames[page];$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));let html=({overview,chapters,downloads}[page]||({papers,practice,notebook}[page]))(params);$('#main').innerHTML=html;typeset($('#main'));document.body.classList.toggle('large-type',!!state.font);document.body.classList.toggle('dark',!!state.dark);bindFilters(page);}
 function bindFilters(page){if(page==='papers'){let commit=()=>{expandedLimit=60;navigate('papers',Object.fromEntries([['year',$('#paper-year').value],['chapter',$('#paper-chapter').value],['q',$('#paper-search').value]].filter(x=>x[1])));};$('#paper-year').onchange=commit;$('#paper-chapter').onchange=commit;$('#paper-search').onkeydown=e=>{if(e.key==='Enter')commit();};$('#paper-search').onchange=commit;}if(page==='practice'){let commit=()=>navigate('practice',Object.fromEntries([['chapter',$('#practice-chapter').value],['group',$('#practice-group').value]].filter(x=>x[1])));$('#practice-chapter').onchange=commit;$('#practice-group').onchange=commit;}}
 function actionButtons(q){let st=state.questions[q.id]||{};return ['done','wrong','star'].map((k,i)=>`<button data-action="mark" data-mark="${k}" class="${st[k]?'selected':''}">${st[k]?['已掌握 ✓','待复盘 ✓','已收藏 ★'][i]:['标记掌握','需要复盘','收藏此题 ☆'][i]}</button>`).join('');}
 function openQuestion(id,queue){let q=byId.get(id);if(!q)return;current=q;currentQueue=queue?.length?queue:(window.currentFiltered||questions);if(!currentQueue.some(x=>x.id===id))currentQueue=all;currentIndex=currentQueue.findIndex(x=>x.id===id);state.questions[id]={...(state.questions[id]||{}),readAt:Date.now()};save();let st=state.questions[id];$('#reader-position').textContent=(q.training?q.ref:q.year+'年 第'+q.ref+'题')+` · ${currentIndex+1}/${currentQueue.length}`;
  $('#reader-body').innerHTML=`<p class="reader-label">${q.training?q.group+' / 原创训练':q.year+'年中山大学信号与系统'}</p><h1 class="reader-title">${escape(q.title)}</h1><div class="tags">${tags(q)}</div><div class="reader-actions">${actionButtons(q)}</div><section class="lesson"><h2>题意与已知</h2>${md(q.statement||q.summary)}${q.sourcePages?.length&&!q.training?`<details><summary>核对原题页（点击可放大）</summary><div class="source-pages">${q.sourcePages.map(p=>`<figure><img src="sources/${q.year}_${p}.webp" loading="lazy" data-expand alt="${q.year}年原题PDF第${p}页"><figcaption>原资料第${p}页</figcaption></figure>`).join('')}</div></details>`:''}<div class="step-box"><strong>第一步，为什么这样想</strong>${md(q.firstStep||'先明确所给条件、输入的定义域和需要判断的性质，再选择时域或变换域。')}</div>${q.training?`<details class="full-solution"><summary>完成后，展开详细推导与答案</summary><div>${md(q.solution)}</div>${renderFigures(q)}<div class="answer-box"><strong>关键结果</strong>${md(q.answer||'见上方推导。')}</div></details>`:`<h2>详细推导</h2>${md(q.solution)}${renderFigures(q)}<div class="answer-box"><strong>关键结果</strong>${md(q.answer||'见上方推导。')}</div>`}${q.pitfalls?.length?`<h2>易错点与检查</h2><ul>${q.pitfalls.map(x=>`<li>${md(x)}</li>`).join('')}</ul>`:''}${q.oppenheim?`<p class="muted">配套原书索引：${escape(q.oppenheim)}</p>`:''}<h2>我的复盘笔记</h2><textarea id="question-note" data-id="${escape(q.id)}" placeholder="记录这题第一步卡在哪里、哪个条件漏看了…">${escape(st.note||'')}</textarea><p class="muted" style="font-size:12px">输入后自动保存在本机。</p></section>`;
  typeset($('#reader-body'));$('#prev-question').disabled=currentIndex===0;$('#next-question').disabled=currentIndex>=currentQueue.length-1;if(!$('#reader').open)$('#reader').showModal();$('#reader').scrollTop=0;
  $('#question-note').oninput=e=>{let id=e.target.dataset.id;state.questions[id]={...(state.questions[id]||{}),note:e.target.value,updatedAt:Date.now()};clearTimeout(save.timer);save.timer=setTimeout(save,400);};
 }
 function renderFigures(q){return (q.figures||[]).map((f,i)=>{let path=typeof f==='string'?f:f.path||f.file||f.src;let caption=typeof f==='string'?`对应图解 ${i+1}`:f.caption||f.title||`对应图解 ${i+1}`;return path?`<figure class="figure"><img src="assets/${escape(path.replace(/^.*assets\//,''))}" alt="${escape(caption)}" loading="lazy" data-expand><figcaption>${escape(caption)}</figcaption></figure>`:'';}).join('');}
 function downloadBackup(){let data=JSON.stringify({app:'sysu-signals-study',exportedAt:new Date().toISOString(),state},null,2);if(window.Android?.exportProgress){window.Android.exportProgress(data);return;}let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.href=url;a.download='信号研习室_学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('备份已导出');}
 async function importBackup(file){try{let incoming=JSON.parse(await file.text());if(incoming.app!=='sysu-signals-study'||!incoming.state?.questions)throw Error();let count=0;for(let [id,v]of Object.entries(incoming.state.questions)){if(!byId.has(id)||!v||typeof v!=='object')continue;let local=state.questions[id]||{},localDate=local.updatedAt||local.readAt||0,inDate=v.updatedAt||v.readAt||0;if(inDate>=localDate){state.questions[id]={done:!!v.done,wrong:!!v.wrong,star:!!v.star,note:String(v.note||'').slice(0,50000),readAt:+v.readAt||0,updatedAt:+v.updatedAt||0};count++;}}save();render();toast(`已合并${count}条学习记录`);}catch{toast('无法读取备份，请选择本工具导出的 JSON 文件。');}}
 document.addEventListener('click',e=>{let image=e.target.closest('[data-expand]');if(image){$('#expanded-image').src=image.src;$('#image-dialog').showModal();return;}let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action;if(a==='open')openQuestion(el.dataset.id);if(a==='go')navigate(el.dataset.page);if(a==='mark'&&current){let id=current.id,k=el.dataset.mark;let st=state.questions[id]||{};st[k]=!st[k];if(k==='done'&&st.done)st.wrong=false;if(k==='wrong'&&st.wrong)st.done=false;st.updatedAt=Date.now();state.questions[id]=st;save();$('.reader-actions').innerHTML=actionButtons(current);toast(k==='done'?(st.done?'已标记掌握':'已取消掌握标记'):k==='wrong'?(st.wrong?'已加入待复盘':'已移出待复盘'):(st.star?'已收藏':'已取消收藏'));}if(a==='reset-filter')navigate('papers');if(a==='load-more'){expandedLimit+=60;render();}if(a==='notebook-mode')navigate('notebook',{mode:el.dataset.mode});if(a==='random-training'){randomQueue=[];navigate('practice',{random:'1'});if(route().params.get('random')==='1')render();}if(a==='export')downloadBackup();if(a==='import')$('#import-progress').click();});
 $('#export-progress').onclick=downloadBackup;$('#import-progress').onchange=e=>{if(e.target.files[0])importBackup(e.target.files[0]);e.target.value='';};
 $('#close-reader').onclick=()=>{$('#reader').close();save();render();};$('#reader').addEventListener('close',()=>{save();render();});$('#close-image').onclick=()=>$('#image-dialog').close();$('#prev-question').onclick=()=>openQuestion(currentQueue[currentIndex-1]?.id,currentQueue);$('#next-question').onclick=()=>openQuestion(currentQueue[currentIndex+1]?.id,currentQueue);$('#print-question').onclick=()=>window.print();
 $('#font-toggle').onclick=()=>{state.font=!state.font;document.body.classList.toggle('large-type',state.font);save();};$('#theme-toggle').onclick=()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);save();};
 window.addEventListener('hashchange',()=>{expandedLimit=60;render();window.scrollTo(0,0);});
 render();if('serviceWorker'in navigator&&!location.search.includes('android=1'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
